create or replace function public.supplier_delete_v1(p_supplier_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare v_name text;v_dep integer;begin if not public.supplier_can_delete() then raise exception 'Supplier deletion requires admin or CEO permission.';end if;if length(trim(coalesce(p_reason,'')))<8 then raise exception 'Deletion reason must contain at least 8 characters.';end if;select company_name into v_name from public.suppliers where id=p_supplier_id for update;if not found then raise exception 'Supplier not found.';end if;select (select count(*) from public.quotations where supplier_id=p_supplier_id)+(select count(*) from public.deals where supplier_id=p_supplier_id)+(select count(*) from public.shipments where supplier_id=p_supplier_id)+(select count(*) from public.invoices where supplier_id=p_supplier_id)+(select count(*) from public.payments where supplier_id=p_supplier_id)+(select count(*) from public.inventory_items where supplier_id=p_supplier_id)+(select count(*) from public.shipment_charges where vendor_id=p_supplier_id) into v_dep;if v_dep>0 then raise exception 'Supplier is linked to % operational or financial record(s). Set it to inactive or blocked instead of deleting it.',v_dep;end if;insert into public.supplier_events(supplier_id,event_type,from_value,to_value,reason,performed_by) values(p_supplier_id,'delete_requested',v_name,null,trim(p_reason),auth.uid());delete from public.suppliers where id=p_supplier_id;end$$;
revoke all on function public.supplier_delete_v1(uuid,text) from public;grant execute on function public.supplier_delete_v1(uuid,text) to authenticated,service_role;
create or replace function public.supplier_account_snapshot_v1(p_supplier_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare v_supplier public.suppliers;v_open_payables integer;v_payable_value numeric;v_quotations integer;v_deals integer;v_shipments integer;v_payments integer;v_charges integer;v_charge_value numeric;v_inventory_items integer;v_risk integer:=0;v_last timestamptz;begin select * into v_supplier from public.suppliers where id=p_supplier_id;if not found then raise exception 'Supplier not found.';end if;select count(*),coalesce(sum(total_amount),0) into v_open_payables,v_payable_value from public.invoices where supplier_id=p_supplier_id and invoice_type='payable' and status not in('paid','cancelled');select count(*) into v_quotations from public.quotations where supplier_id=p_supplier_id;select count(*) into v_deals from public.deals where supplier_id=p_supplier_id;select count(*) into v_shipments from public.shipments where supplier_id=p_supplier_id;select count(*) into v_payments from public.payments where supplier_id=p_supplier_id and payment_type='payment' and status<>'cancelled';select count(*),coalesce(sum(coalesce(actual_amount,estimated_amount,0)),0) into v_charges,v_charge_value from public.shipment_charges where vendor_id=p_supplier_id;select count(*) into v_inventory_items from public.inventory_items where supplier_id=p_supplier_id;select max(created_at) into v_last from public.supplier_events where supplier_id=p_supplier_id;if v_supplier.status='blocked' then v_risk:=v_risk+45;elsif v_supplier.status='inactive' then v_risk:=v_risk+15;elsif v_supplier.status='pending' then v_risk:=v_risk+10;end if;if v_supplier.kyc_status='rejected' then v_risk:=v_risk+45;elsif v_supplier.kyc_status='expired' then v_risk:=v_risk+30;elsif coalesce(v_supplier.kyc_status,'pending')<>'approved' then v_risk:=v_risk+15;end if;if coalesce(v_supplier.rating,0)>0 and v_supplier.rating<3 then v_risk:=v_risk+20;end if;if v_supplier.registration_number is null then v_risk:=v_risk+5;end if;if v_supplier.tax_number is null then v_risk:=v_risk+5;end if;if v_supplier.contact_person is null or v_supplier.email is null then v_risk:=v_risk+5;end if;v_risk:=least(v_risk,100);return jsonb_build_object('quotations',v_quotations,'deals',v_deals,'shipments',v_shipments,'open_payables',v_open_payables,'open_payable_value',v_payable_value,'payments',v_payments,'charges',v_charges,'charge_value',v_charge_value,'inventory_items',v_inventory_items,'risk_score',v_risk,'risk_band',case when v_risk>=60 then 'high' when v_risk>=30 then 'watch' else 'normal' end,'last_event_at',v_last);end$$;
revoke all on function public.supplier_account_snapshot_v1(uuid) from public;grant execute on function public.supplier_account_snapshot_v1(uuid) to authenticated,service_role;revoke delete on public.suppliers from authenticated;
